INSERT INTO ccd_indicators VALUES('01-01-00-00-00-01','01-01-00-00-00','01','Angka Partisipasi Kasar (APK) jenjang PAUD, SD, SMP','Persen','100',100.0,100.0,100.0,100.0,100.0,'Indikator ini dipilih untuk mengetahui Jumlah APK ','Jumlah Peserta Didik pada jenjang PAUD, SD sederajat dan SMP sederajat Dibagi Jumlah Penduduk Usia Sekolah  (5 – 15 tahun) Kabupaten/kota tersebut x100%','Komulatif','Pembilang : Jumlah anak usia 5-15 tahun yang  sedang mengikuti pendidikan anak usia dini, Sekolah Dasar, Sekolah Menengah  baik negeri maupun swasta (kelompok bermain, raudhatul athfal, taman kanak-kanak, satuan paud sejenis, dan Taman Pendidikan Al-Quran, Sekolah Dasar negeri dan Swasta, SMP negeri dan Swata ) dalam kurun waktu 1 tahun anggaran pada tahun ajaran baru di daerah kabupaten/kota. Penyebut : Jumlah keseluruhan penduduk (anak) berusia 5-15 tahun di daerah kabupaten/kota yang bersangkutan sesuai dengan data kependudukan.','Dinas Pendidikan, Kepemudaan dan Olahraga, Dindukcapil, data emis kemenag',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-00-00-00-02','01-01-00-00-00','02','Angka Partisipasi Murni (APM) jenjang PAUD, SD, SMP','Persen','80.27',84.2999999999999971,88.5,92.9000000000000056,97.5999999999999943,100.0,'Indikator Ini dipilih untuk mengetahui jumlah APM','Jumlah Penduduk usia 5-15 tahun yang bersekolah dijenjang Pendidikan PAUD, SD dan SMP pada kabupaten tersebut dibagi jumlah Penduduk usia 5– 15 Tahun di Kabupaten kota tersebut x 100%','Komulatif','Pembilang : Jumlah Penduduk usia 5-15 tahun yang  sedang mengikuti pendidikan anak usia dini, Sekolah Dasar, Sekolah Dasar negeri dan Swasta, SMP negeri dan Swata ) dalam kurun waktu 1 tahun anggaran pada tahun ajaran baru di daerah kabupaten/kota. Penyebut : Jumlah keseluruhan penduduk (anak) berusia 5-15 tahun di daerah kabupaten/kota yang bersangkutan sesuai dengan data kependudukan.','Dinas Pendidikan, Kepemudaan dan Olahraga, Dindukcapil, data emis kemenag',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-00-00-00-03','01-01-00-00-00','03','Indeks Capaian Standar Pelayanan Minimal (SPM) Pendidikan','Persen','100',100.0,100.0,100.0,100.0,100.0,'Indikator ini dipilih untuk tolak Ukur pelayanan Minimal Urusan Pendidikan ','Nilai yang dikeluarkan dari Rapor Pendidikan berdasarkan perhitungan hasil ANBK ','Komulatif','Dinas Pendidikan, Kepemudaan dan Olahraga ','Rapor Pendidikan didasarkan pada Peraturan Pemerintah  Permendikbudristek Nomor 32 Tahun 2022 tentang Standar Teknis Pelayanan Minimal Pendidikan',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-01-00-00-01','01-01-01-00-00','01','Persentase Anak Tidak Sekolah (ATS) ','Persen','',7.66999999999999992,7.26999999999999957,6.76999999999999957,6.26999999999999957,5.76999999999999957,'Indikator ini digunakan untuk mengetahui jumlah Anak Tidak Sekolah (ATS) yang melanjutkan ke PKBM','Jumlah Anak Tidak Sekolah dibagi jumlah siswa APS * 100% (data ats keseluruhan berdasarkan dapodik akhir tahun (Desember) ','Non Kumulatif ','Data ATS, iku_defops(Drop Out) dan LTM(Lulus Tidak Melanjutkan) dibagi jumlah Angka Partisipasi Sekolah di akhir tahun dikali 100%. Bersarkan Pedum LPPD','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
