INSERT INTO ccd_indicators VALUES('01-01-01-03-00-02','01-01-01-03-00','02','Angka Literasi SD','Persen','',72.769999999999996,75.269999999999996,77.769999999999996,80.269999999999996,82.769999999999996,'Persentase peserta didik berdasarkan kemampuan dalam memahami, menggunakan, merefleksi, dan mengevaluasi beragam jenis teks (teks informasional dan teks fiksi) untuk jenjang SD.','Persentase pelaksanaan kegiatan yang mendukung capain literasi assesment sumatif akhir semester gasal dan genap dan Assesment Nasional ','Non Kumulatif ','untuk  pelaksanaan kegiatan yang mendukung capain literasi assesment sumatif akhir semester gasal dan genap dan Assesment Nasional, Test Kemampuan Akademik (TKA) Bahasa Iniku_defopsnesia','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
