INSERT INTO ccd_indicators VALUES('01-01-01-03-06-01','01-01-01-03-06','01','Jumlah Siswa yang Mengikuti Ajang Kompetisi/Lomba Akademik dan Non Akademik','Peserta Didik','',21920.0,22000.0,22100.0,22200.0,22300.0,'Untuk mengetahui Jumlah  Siswa      yang      Mengikuti      Ajang Kompetisi/Lomba Akademik dan Non Akademik','Jumlah      Siswa      yang      Mengikuti      Ajang Kompetisi/Lomba Akademik dan Non Akademik','Non Kumulatif ','terwadahinya bakat minat seni ,  olahraga dan akademik dan non akademik bagi murid dari tingkat kecamatan sampai dengan tingkat nasional ','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-01-03-07-01','01-01-01-03-07','01','Jumlah Sekolah Dasar yang Dilaksanakan Pembinaan Kelembagaan dan manajemen sekolah','Satuan Pendidikan','',100.0,150.0,200.0,250.0,300.0,'Untuk mengetahui jumlah sekolah yang dilaksanakan pembinaan','Jumlah sekolah yang dilaksanakan pembinaan','Non Kumulatif ','terselenggaranya kegiatan tujuh kebiasaan anak iniku_defopsnesia hebat dan coding artificial. setiap korwil mengirimkan 5 peserta terdiri dari unsur guru, kepala sekolah, pengawas.','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-01-03-08-01','01-01-01-03-08','01','Jumlah Sekolah Dasar yang Mengelola Dana BOS','Satuan Pendidikan','',616.0,616.0,616.0,616.0,616.0,'Untuk mengetahui Jumlah          Sekolah  Dasar  yang  Mengelola  Dana BOS','Jumlah  Sekolah  Dasar  yang  Mengelola  Dana','Non Kumulatif ','jumlah sekolah yang menerima dana BOS. Dana bos yang disalurkan setiap sekolah berdasarkan jumlah siswa. Besaran per siswa Rp. 900. 000 per siswa per tahun','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-01-03-09-01','01-01-01-03-09','01','Jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang Pendidikan yang dilaksanakan','Dokumen','',2.0,2.0,2.0,2.0,2.0,'Untuk mengetahui jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang pendidikan','Jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang Pendidikan yang dilaksanakan','Non Kumulatif ','untuk workshop penyusunan soal tingkat sekolah dengan output soal tingkat kecamatan. Dengan peserta tiap kecamatan sebanyak 120 orang dengan output 1200 paket soal. 2 kegiatan untuk assesment sumatif Gasal dan genap','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-01-03-10-01','01-01-01-03-10','01','Jumlah Ruang Kelas Baru yang Bertambah','Ruang','',10.0,15.0,20.0,25.0,30.0,'Untuk mengetahui Jumlah  Ruang Kelas Baru yang Bertambah','Jumlah  Ruang Kelas Baru yang Bertambah','Non Kumulatif ','jumlah raung kelas baru yang bertambah dengan rincian minimal 1 sekolah 2 ruang ','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-01-03-11-01','01-01-01-03-11','01','Jumlah Sarana, Prasarana dan Utilitas Sekolah yang Telah Direhabilitasi Sedang/Berat','Ruang','',525.0,550.0,650.0,700.0,825.0,'untuk mengetahui Rehabilitasi Sedang/Berat Sarana, Prasarana dan Utilitas Sekolah         ','jumlah Rehabilitasi Sedang/Berat Sarana, Prasarana dan Utilitas Sekolah         ','Non Kumulatif ','Digunakan untuk merehabilitasi sedang berat sarana prasrana dan utilitas sekolah yang direhab berupa : ruang bermain, ruang gedung, ruang guru, ruang ibadah, ruang kelas, ruang kepala sekolah, ruang lab tk, ruang lab ipa, ruag perpustakaan, ruang sirkulasi, ruang toilet, ruang uks, rumah dinas, , bangunan pagar keliling, bangunan paving, sarana air bersih, bangunan talud. ','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-01-03-12-01','01-01-01-03-12','01','Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Orang','',676.0,676.0,676.0,676.0,676.0,'Untuk mengetahui Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Non Kumulatif ','Jumlah sekolah yang mengikuti bimbingan teknis ditambah dengan jumlah tim managemen bos tingkat kecamatan. Masing masing kecamatan berjumlah 3 orang dalam 1 tim','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
INSERT INTO ccd_indicators VALUES('01-01-01-03-13-01','01-01-01-03-13','01','Jumlah Satuan Pendidikan yang Menyelenggarakan Proses Belajar','Peserta Didik','',616.0,616.0,616.0,616.0,616.0,'Untuk mengetahui Jumlah Satuan Pendidikan yang Menyelenggarakan Proses Belajar','Jumlah Satuan Pendidikan yang Menyelenggarakan Proses Belajar','Non Kumulatif ','Untuk kegiatan assesment sumatif akhir semester, akhir jenjang dan assesment nasional, untuk Kegiatan Test Kemampuan Akademik (TKA) untuk kelas 6 mulai tahun 2026  untuk siswa. Siswa yang mengikuti TKA mendapatkan Sertifikat sebagai syarat untuk melanjutkan ke jenjang selanjutnya. Program ini diluncurkan oleh Kementrian pendidikan Dasar dan Menengah','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
