INSERT INTO ccd_indicators VALUES('02-02-02-00-00-01','02-02-02-00-00','01','Persentase pemuda yang menjadi anggota aktif pada organisasi kepemudaan','Persen','',81.0,82.0,83.0,84.0,85.0,'indikator ini digunakan untuk mengetahui jumlah pemuda usia 16-30 tahun yang menjadi anggota aktif pada organisasi kepemudaan dan organisasi ','Jumlah pemuda usia (16-30) tahun yang menjadi anggota aktif pada Organisasi kepemudaan dan Organisasi sosial kemasyarakatan di kabupaten/kota dibagi  Jumlah pemuda usia (16-30) tahun di kabupaten/kota X 100%','Non Kumulatif ','dibatasi untuk organisasi kepemudaan (Muhammadiyah, karangktaruna). Syarat organisasi aktif adalah minimal melaksanakan kegiatan minimal 3 kali dalam setahun.  Pembilang : Jumlah Pemuda usia (16-30) tahun yang menjadi anggota aktif organisasi kepemudaan dan organisasi sosial kemasyarakatan yang didirikan dan dibentuk oleh masyarakat secara sukarela berdasarkan kesamaan aspirasi, kehendak, kebutuhan, kepentingan, kegiatan dan tujuan untuk berpartisipasi dalam pembangunan demi tercapainya tujuan NKRI yang berdasarkan Pancasila. Penyebut : Jumlah pemuda (16-30) tahun di kabupaten/kota berdasarkan data kependudukan di Kabupaten/kota yang terdaftar pada Sistem Informasi Administrasi Kependudukan (SIAK).','Dinas Pendidikan, Kepemudaan dan Olahraga',NULL,NULL,NULL);
