PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "ccd_indicators" ("master_ik" varchar not null, "master_id" varchar not null, "ik_id" varchar not null, "indikator" text not null, "satuan" varchar not null, "baseline" varchar, "t1" float, "t2" float, "t3" float, "t4" float, "t5" float, "iku_alasan" text, "iku_formulasi" text, "iku_tipehitung" text, "iku_do" text, "iku_sumberdata" text, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, primary key ("master_ik"));
COMMIT;
